import{_ as l,C as n,o as e,c as d,a3 as i,b as r,w as a,a as o,E as h,a2 as c}from"./chunks/framework.CDCjIvJ8.js";const x=JSON.parse('{"title":"Security model","description":"","frontmatter":{},"headers":[],"relativePath":"security/model.md","filePath":"security/model.md","lastUpdated":1789296458000}'),g={name:"security/model.md"};function p(u,t,y,k,f,m){const s=n("Mermaid");return e(),d("div",null,[t[1]||(t[1]=i('<h1 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h1><h2 id="governing-principle" tabindex="-1">Governing principle <a class="header-anchor" href="#governing-principle" aria-label="Permalink to &quot;Governing principle&quot;">​</a></h2><p><strong>The token establishes <em>who</em> the caller is. The database decides <em>what</em> they may do.</strong></p><p>Everything below follows from that sentence. The original system violated it — the role travelled in the token, and the client chose it — which is how a dropdown on the sign-up form became a privilege-escalation vector.</p><h2 id="trust-boundaries" tabindex="-1">Trust boundaries <a class="header-anchor" href="#trust-boundaries" aria-label="Permalink to &quot;Trust boundaries&quot;">​</a></h2>',5)),(e(),r(c,null,{default:a(()=>[h(s,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Untrusted%5B%22Untrusted%22%5D%0A%20%20%20%20%20%20%20%20Browser%5B%22Browser%22%5D%0A%20%20%20%20%20%20%20%20Upload%5B%22Uploaded%20files%22%5D%0A%20%20%20%20%20%20%20%20Email%5B%22Email%20addresses%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Edge%5B%22Edge%20%E2%80%94%20Cloudflare%22%5D%0A%20%20%20%20%20%20%20%20WAF%5B%22WAF%20%C2%B7%20coarse%20rate%20limiting%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20App%5B%22Application%20%E2%80%94%20semi-trusted%22%5D%0A%20%20%20%20%20%20%20%20Host%5B%22Host%20allowlist%22%5D%0A%20%20%20%20%20%20%20%20Cors%5B%22Exact-origin%20CORS%22%5D%0A%20%20%20%20%20%20%20%20Body%5B%22Streaming%20body%20cap%22%5D%0A%20%20%20%20%20%20%20%20Jws%5B%22Local%20JWS%20verification%22%5D%0A%20%20%20%20%20%20%20%20Role%5B%22Role%20from%20database%22%5D%0A%20%20%20%20%20%20%20%20Own%5B%22Per-resource%20ownership%22%5D%0A%20%20%20%20%20%20%20%20Limit%5B%22Redis%20limiter%20%2B%20token%20budget%22%5D%0A%20%20%20%20%20%20%20%20Magic%5B%22Magic-byte%20file%20validation%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Trusted%5B%22Trusted%20%E2%80%94%20Postgres%22%5D%0A%20%20%20%20%20%20%20%20RLS%5B%22Row-level%20security%22%5D%0A%20%20%20%20%20%20%20%20Col%5B%22Column%20grants%3Cbr%2F%3E(answer%20keys%20withheld)%22%5D%0A%20%20%20%20%20%20%20%20Audit%5B%22Append-only%20audit%20log%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Browser%20--%3E%20WAF%20--%3E%20Host%20--%3E%20Cors%20--%3E%20Body%20--%3E%20Jws%20--%3E%20Role%20--%3E%20Own%20--%3E%20Limit%20--%3E%20RLS%0A%20%20%20%20Upload%20--%3E%20Magic%20--%3E%20Own%0A%20%20%20%20Email%20--%3E%20Limit%0A%0A%20%20%20%20RLS%20--%3E%20Col%0A%20%20%20%20Own%20--%3E%20Audit%0A%0A%20%20%20%20style%20Untrusted%20fill%3A%23fef2f2%2Cstroke%3A%23ef4444%0A%20%20%20%20style%20App%20fill%3A%23fffbeb%2Cstroke%3A%23f59e0b%0A%20%20%20%20style%20Trusted%20fill%3A%23f0fdf4%2Cstroke%3A%2322c55e%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=i(`<p>The application layer is <strong>semi-trusted</strong>: it enforces authorization, but the database enforces it again. That redundancy is the point — a missing check in a new endpoint is a bug, not a breach.</p><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><h3 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h3><p>Supabase-issued JWTs, verified <strong>locally</strong> against the project&#39;s JWKS (or the shared secret for legacy HS256 projects), with full claim validation: <code>iss</code>, <code>aud</code>, <code>exp</code>, <code>nbf</code>, <code>iat</code>, <code>sub</code>.</p><p>The previous implementation called <code>supabase.auth.get_user(token)</code> on every request. That put a network round trip in front of every endpoint — 100–300 ms — and made Supabase Auth a hard availability dependency. <code>SUPABASE_JWT_SECRET</code> was configured but never used.</p><div class="danger custom-block"><p class="custom-block-title">Algorithm confusion</p><p>Supporting both key families is the hazard. If permitted algorithms came from the token&#39;s own header, an attacker could take a public RSA key from the JWKS, sign a token with it as an <strong>HMAC secret</strong>, set <code>alg: HS256</code>, and have it verify.</p><p>The permitted algorithm is therefore derived from <strong>the key that was selected</strong>, never from header input. The symmetric and asymmetric sets are disjoint, and <code>none</code> is absent by construction. Pinned by tests in <code>tests/security/test_auth_hardening.py</code>.</p></div><h3 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h3><p>Three independent layers:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Answers</th><th style="text-align:left;">Where</th></tr></thead><tbody><tr><td style="text-align:left;">Role gate</td><td style="text-align:left;">May this <em>kind</em> of user call this endpoint?</td><td style="text-align:left;"><code>require_student</code> / <code>require_teacher</code> / <code>require_admin</code></td></tr><tr><td style="text-align:left;">Ownership check</td><td style="text-align:left;">May <em>this</em> user touch <em>this</em> row?</td><td style="text-align:left;"><code>app/core/authorization.py</code></td></tr><tr><td style="text-align:left;">Row-level security</td><td style="text-align:left;">Would the database permit it anyway?</td><td style="text-align:left;">Migration 005</td></tr></tbody></table><p>The middle layer is the one that was missing. Role gates confirmed the caller was <em>a</em> student or <em>a</em> teacher and then matched records on a caller-supplied id.</p><div class="warning custom-block"><p class="custom-block-title">Four broken-access-control bugs, all fixed</p><ul><li><code>GET /evaluations/{id}</code> returned any student&#39;s scores and draft evidence to any authenticated caller.</li><li><code>GET /loopholes/{id}</code> did the same, reaching through to draft contents.</li><li><code>POST /submissions/{id}/override</code> let <strong>any</strong> teacher rewrite the grade on <strong>any</strong> submission, including another instructor&#39;s cohort.</li><li><code>POST /submissions</code> accepted a <code>draft_id</code> on trust, so a student could submit another student&#39;s draft as their own.</li><li><code>PATCH /roadmap/items/{id}/complete</code> updated by bare id; <code>roadmap_items</code> has no user column, so ownership requires a join through <code>roadmaps</code>.</li></ul></div><p>Cross-tenant attempts return <strong>404, not 403</strong>. A 403 confirms the row exists.</p><h3 id="roles-are-server-assigned" tabindex="-1">Roles are server-assigned <a class="header-anchor" href="#roles-are-server-assigned" aria-label="Permalink to &quot;Roles are server-assigned&quot;">​</a></h3><p><code>role</code> is absent from every request schema, and the schemas use <code>extra=&quot;forbid&quot;</code> so a client still sending one <strong>fails loudly</strong> rather than being silently ignored. <code>ADMIN</code> is never granted implicitly.</p><p><code>ensure_profile</code> replaced <code>upsert_profile</code>, which rewrote every column on each call — so an ordinary login could overwrite a stored role. Role changes go through the audited <code>set_role</code>.</p><h3 id="rate-limiting-and-budgets" tabindex="-1">Rate limiting and budgets <a class="header-anchor" href="#rate-limiting-and-budgets" aria-label="Permalink to &quot;Rate limiting and budgets&quot;">​</a></h3><p>Redis sliding-window counters, evaluated atomically in Lua, with separate scopes:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Scope</th><th style="text-align:left;">Default</th><th style="text-align:left;">Protects against</th></tr></thead><tbody><tr><td style="text-align:left;"><code>AUTH</code></td><td style="text-align:left;">5/min, 30/hr</td><td style="text-align:left;">Credential stuffing, token guessing</td></tr><tr><td style="text-align:left;"><code>LLM</code></td><td style="text-align:left;">10/min, 300/day</td><td style="text-align:left;">Unbounded inference spend</td></tr><tr><td style="text-align:left;"><code>UPLOAD</code></td><td style="text-align:left;">40/hr</td><td style="text-align:left;">Storage and parsing abuse</td></tr><tr><td style="text-align:left;"><code>INVITE</code></td><td style="text-align:left;">200/hr</td><td style="text-align:left;">Mail-reputation damage</td></tr><tr><td style="text-align:left;"><code>DEFAULT</code></td><td style="text-align:left;">120/min</td><td style="text-align:left;">General abuse</td></tr></tbody></table><p>Plus a <strong>per-user daily token budget</strong>, because request counts cannot bound spend — one long-context call may cost a hundred times another.</p><p>Keyed by user id where available, so an institution behind one NAT does not share a bucket. Fails <strong>closed</strong> when <code>REDIS_REQUIRED</code>, which production forces on along with <code>RATE_LIMIT_ENABLED</code>.</p><h3 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">The highest-severity baseline finding</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">allow_origin_regex </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">^</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">https</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">://</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">localhost</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">127</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\.</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">0</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\.</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">0</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\.</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)(</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">^</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">https://</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\.</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">onrender</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\.</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">allow_credentials </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> True</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Every <code>*.onrender.com</code> subdomain — a hostname anyone obtains by deploying there — could make credentialed cross-origin requests and read the responses.</p></div><p>Now an exact allowlist, validated at startup: <code>*</code> rejected, https required in production, and localhost never injected in production.</p><h3 id="uploads" tabindex="-1">Uploads <a class="header-anchor" href="#uploads" aria-label="Permalink to &quot;Uploads&quot;">​</a></h3><p>Content type is decided by <strong>inspecting the leading bytes</strong>. The previous guard read <code>if file.content_type and ...</code> — omitting the header skipped validation entirely — and otherwise trusted a client-supplied extension.</p><ul><li>DOCX verified as genuine WordprocessingML, not merely a ZIP.</li><li>Compression-ratio and uncompressed-size ceilings reject decompression bombs.</li><li>PDFs rejected if encrypted or over 500 pages.</li><li>Filenames sanitized before building any storage path: directory traversal, control characters and RTL-override disguises all stripped.</li><li>The extension must agree with what the bytes actually are.</li></ul><h3 id="error-handling" tabindex="-1">Error handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error handling&quot;">​</a></h3><p>Uniform envelope, always:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;permission_denied&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;detail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;request_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a1b2c3…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Upstream text never reaches the client. Handlers previously echoed Supabase errors, storage bucket paths, rubric filesystem paths, and — in the Groq provider — the full upstream response body.</p><p>Secrets are redacted <strong>at the logging sink</strong>, not at call sites. Relying on every call site to remember is a losing strategy.</p><h3 id="audit-trail" tabindex="-1">Audit trail <a class="header-anchor" href="#audit-trail" aria-label="Permalink to &quot;Audit trail&quot;">​</a></h3><p>Privileged actions are recorded append-only: grade overrides, role grants, reference uploads, invitations issued, revoked and accepted. Migration 005 grants no <code>UPDATE</code> or <code>DELETE</code>, so a compromised session cannot rewrite its own history. Writes are best-effort — an audit failure never fails the action it describes.</p><h2 id="baseline-findings" tabindex="-1">Baseline findings <a class="header-anchor" href="#baseline-findings" aria-label="Permalink to &quot;Baseline findings&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">#</th><th style="text-align:left;">Finding</th><th style="text-align:left;">Severity</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:left;">Role self-assignment at registration</td><td style="text-align:left;">Critical</td><td style="text-align:left;">Fixed</td></tr><tr><td style="text-align:right;">2</td><td style="text-align:left;">Role escalation via <code>user_metadata</code></td><td style="text-align:left;">Critical</td><td style="text-align:left;">Fixed</td></tr><tr><td style="text-align:right;">3</td><td style="text-align:left;">CORS trusting every <code>*.onrender.com</code> with credentials</td><td style="text-align:left;">Critical</td><td style="text-align:left;">Fixed</td></tr><tr><td style="text-align:right;">4</td><td style="text-align:left;">No RLS on 23 tables; service-role key everywhere</td><td style="text-align:left;">Critical</td><td style="text-align:left;">Migration 005</td></tr><tr><td style="text-align:right;">5</td><td style="text-align:left;">Per-request Supabase auth round trip</td><td style="text-align:left;">Critical</td><td style="text-align:left;">Fixed</td></tr><tr><td style="text-align:right;">6</td><td style="text-align:left;">No rate limiting anywhere</td><td style="text-align:left;">Critical</td><td style="text-align:left;">Fixed</td></tr><tr><td style="text-align:right;">7</td><td style="text-align:left;">Bypassable file-type validation</td><td style="text-align:left;">High</td><td style="text-align:left;">Fixed</td></tr><tr><td style="text-align:right;">8</td><td style="text-align:left;">Upstream exception text leaked to clients</td><td style="text-align:left;">High</td><td style="text-align:left;">Fixed</td></tr><tr><td style="text-align:right;">9</td><td style="text-align:left;">No security headers; docs public in production</td><td style="text-align:left;">High</td><td style="text-align:left;">Fixed</td></tr><tr><td style="text-align:right;">10</td><td style="text-align:left;">Broken object-level authorization (×5)</td><td style="text-align:left;">High</td><td style="text-align:left;">Fixed</td></tr><tr><td style="text-align:right;">11</td><td style="text-align:left;">Answer keys readable by students</td><td style="text-align:left;">Medium</td><td style="text-align:left;">Column grants</td></tr><tr><td style="text-align:right;">12</td><td style="text-align:left;">Leaderboard and analytics unscoped across all students</td><td style="text-align:left;">Medium</td><td style="text-align:left;">Class-scoped</td></tr><tr><td style="text-align:right;">13</td><td style="text-align:left;"><code>/documents/classify</code> fully unauthenticated</td><td style="text-align:left;">Medium</td><td style="text-align:left;">Fixed</td></tr><tr><td style="text-align:right;">14</td><td style="text-align:left;">Unused <code>python-jose</code> and <code>passlib</code></td><td style="text-align:left;">Medium</td><td style="text-align:left;">Removed</td></tr><tr><td style="text-align:right;">15</td><td style="text-align:left;">No audit trail on privileged actions</td><td style="text-align:left;">Medium</td><td style="text-align:left;">Added</td></tr><tr><td style="text-align:right;">16</td><td style="text-align:left;">Container ran as root</td><td style="text-align:left;">Medium</td><td style="text-align:left;">Non-root, CI-enforced</td></tr><tr><td style="text-align:right;">17</td><td style="text-align:left;">Demo credentials in the shipped bundle</td><td style="text-align:left;">Low</td><td style="text-align:left;">Removed</td></tr></tbody></table><h2 id="known-gaps" tabindex="-1">Known gaps <a class="header-anchor" href="#known-gaps" aria-label="Permalink to &quot;Known gaps&quot;">​</a></h2><p>Stated plainly rather than omitted:</p><ul><li><strong>Repositories still use the service-role key</strong>, which is <code>BYPASSRLS</code>. The policies in migration 005 defend against key leakage and direct database access today; making them the enforcement boundary for the API itself requires migrating repositories onto <code>get_user_scoped_client()</code>. That groundwork is in place.</li><li><strong>Tokens live in <code>localStorage</code></strong>, so an XSS would expose them. Mitigated by a strict CSP and React&#39;s default escaping; httpOnly cookies are the real fix.</li><li><strong>Prompt-injection defences on the tutor path are not yet implemented.</strong> A student can put instructions in a draft that the tutor reads.</li><li><strong>No automated dependency-update pipeline</strong> beyond nightly advisory scanning.</li></ul><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><p>Security issues should go to the maintainers privately rather than through a public issue.</p>`,40))])}const E=l(g,[["render",p]]);export{x as __pageData,E as default};
